{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Resonant gatherings and private sessions rooted in steady practice and clear intention. Book a session or try a short guided micro-practice now." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container">
      <a class="brand" href="/index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Main navigation">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Offerings</a>
        <a href="/pricing.html">Investments</a>
        <a href="/about.html">Our Approach</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero reveal" id="hero">
      <div class="container grid">
        <div>
          <h1 class="kicker">An open hour to re-anchor</h1>
          <p class="lead">Join small-group sound experiences and focused private sessions that help you step out of noise and back into clear presence.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button id="tryNowBtn" class="btn ghost">Try the 6-minute practice</button>
          </div>
          <p class="muted">Upcoming in {{CITY}}, {{STATE}} • <a href="/events.html">See all dates</a></p>
        </div>
        <div class="pattern-panel" aria-hidden="true">
          <!-- Decorative SVG pattern served via CSS background and inline fallback -->
          <svg viewBox="0 0 400 300" class="pattern-fallback" preserveAspectRatio="xMidYMid meet">
            <rect width="100%" height="100%" fill="url(#pat)" />
            <defs>
              <pattern id="pat" width="20" height="20" patternUnits="userSpaceOnUse">
                <rect width="10" height="10" fill="#f6efe6"></rect>
                <rect x="10" y="10" width="10" height="10" fill="#efe1d1"></rect>
              </pattern>
            </defs>
          </svg>
        </div>
      </div>
    </section>

    <section class="social-proof reveal" id="trust">
      <div class="container">
        <h2>What folks say after a gathering</h2>
        <div class="testimonials grid">
          <blockquote>
            "A clear, practical reset—arrived distracted, left with focus." <cite>— Audiofacilitator</cite>
          </blockquote>
          <blockquote>
            "The leader gives simple cues; the sound helps me land. I use the short practice at my desk now." <cite>— Local attendee</cite>
          </blockquote>
        </div>
      </div>
    </section>

    <section class="benefits reveal" id="benefits">
      <div class="container">
        <h2>How our gatherings help you</h2>
        <ul class="benefit-list">
          <li><strong>Practical clarity:</strong> Tools and sound cues you can use after the session.</li>
          <li><strong>Accessible format:</strong> Walk-in events and private sessions tailored to needs.</li>
          <li><strong>Short to deep:</strong> Options from 30-minute refreshers to longer restorative sessions.</li>
        </ul>
      </div>
    </section>

    <section class="process reveal" id="process">
      <div class="container">
        <h2>How a session proceeds</h2>
        <ol class="process-steps">
          <li><strong>Arrival & short orientation:</strong> Set a personal intention and settle in.</li>
          <li><strong>Guided sound practice:</strong> Layered tones and breath cues for steadying attention.</li>
          <li><strong>Gentle transition:</strong> Grounding prompts and quiet journaling time.</li>
        </ol>
      </div>
    </section>

    <section class="faq reveal" id="faq">
      <div class="container">
        <h2>Common questions & safety notes</h2>
        <details>
          <summary>Is this suitable if I'm anxious or new to sound?</summary>
          <p>Yes. Sessions are paced simply and include verbal cues. You may remain seated, keep your eyes open, or use ear protection if that helps you ease in.</p>
        </details>
        <details>
          <summary>Contraindications</summary>
          <p class="disclaimer">Sound sessions are generally safe for most people, but they may not be appropriate for anyone with recent head/neck injury, uncontrolled epilepsy, a history of severe psychosis, or pregnancy complications without practitioner clearance. If you have concerns, please consult your healthcare provider before attending and email us at {{EMAIL}} for a pre-session consultation.</p>
        </details>
      </div>
    </section>

    <section class="cta reveal" id="final-cta">
      <div class="container">
        <h2>Begin here</h2>
        <p>Reserve a seat at an upcoming gathering or arrange a focused private session for a team or small group.</p>
        <div class="actions">
          <a class="btn primary" href="/book.html">Reserve a Place</a>
          <a class="btn ghost" href="/contact.html">Contact Us</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <nav class="footer-nav">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Offerings</a>
        <a href="/pricing.html">Investments</a>
        <a href="/about.html">Our Approach</a>
        <a href="/faq.html">FAQ</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <p class="contact">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <p class="muted">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved</p>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="tryModal" class="modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="modalTitle">
    <div class="modal-panel">
      <button id="closeModal" class="modal-close" aria-label="Close">✕</button>
      <h3 id="modalTitle">Short Guided Practice</h3>
      <div id="exercise" class="exercise">
        <p id="exercisePrompt">Get comfortable. We'll guide a 6-minute micro-practice: breath, short journaling, and intention setting.</p>
        <div id="exerciseVisual" class="visual" aria-hidden="true"></div>
        <div class="exercise-controls">
          <button id="startExercise" class="btn primary">Start 6-min Practice</button>
          <button id="skipToJournal" class="btn ghost">Jump to journaling</button>
        </div>
        <div id="journalArea" class="journal hidden">
          <label for="journalInput">Write a quick note or intention (optional)</label>
          <textarea id="journalInput" rows="4" placeholder="A short sentence to hold as you go..." aria-label="Journal input"></textarea>
          <div class="journal-actions">
            <button id="saveJournal" class="btn primary">Save Intention</button>
            <button id="closeAndReturn" class="btn ghost">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
